<section class="voices-section section pattern" aria-labelledby="voices-heading"><div class="container voices-layout"><h2 class="eyebrow" id="voices-heading"><?php rzz_text('voices_label','Client voices'); ?></h2><div data-carousel><?php $reviews=get_posts(['post_type'=>'review','numberposts'=>-1,'orderby'=>'menu_order','order'=>'ASC']);if($reviews):foreach($reviews as $i=>$post):setup_postdata($post); ?><figure class="voice" data-slide <?php if($i)echo 'hidden'; ?>><span class="quote-mark" aria-hidden="true">“</span><blockquote><?php the_content(); ?></blockquote><figcaption><?php the_title(); ?><small><?php echo esc_html(rzz_meta('company')); ?></small></figcaption></figure><?php endforeach;wp_reset_postdata();if(count($reviews)>1): ?><div class="carousel-controls"><button data-prev aria-label="Previous testimonial">←</button><button data-next aria-label="Next testimonial">→</button><span data-counter aria-live="polite"></span></div><?php endif;else: ?><p class="voice-empty"><?php rzz_text('voices_empty','Confidence begins with a conversation. Speak to our team about the legal support you need.'); ?></p><?php endif; ?></div></div></section>